CREATE     PROCEDURE [synapse_fo].[usp_Update_MAINACCOUNT]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:46
	Description: Update stored procedure for MAINACCOUNT from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[ACCOUNTCATEGORYREF] = stg.[ACCOUNTCATEGORYREF],
		tgt.[ADJUSTMENTMETHOD_MX] = stg.[ADJUSTMENTMETHOD_MX],
		tgt.[CLOSETYPE] = stg.[CLOSETYPE],
		tgt.[CLOSING] = stg.[CLOSING],
		tgt.[CONSOLIDATIONMAINACCOUNT] = stg.[CONSOLIDATIONMAINACCOUNT],
		tgt.[CREATEDBY] = stg.[CREATEDBY],
		tgt.[CREATEDDATETIME] = stg.[CREATEDDATETIME],
		tgt.[CURRENCYCODE] = stg.[CURRENCYCODE],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		tgt.[DEBITCREDITBALANCEDEMAND] = stg.[DEBITCREDITBALANCEDEMAND],
		tgt.[DEBITCREDITCHECK] = stg.[DEBITCREDITCHECK],
		tgt.[DEBITCREDITPROPOSAL] = stg.[DEBITCREDITPROPOSAL],
		tgt.[EXCHANGEADJUSTED] = stg.[EXCHANGEADJUSTED],
		tgt.[EXCHANGEADJUSTMENTRATETYPE] = stg.[EXCHANGEADJUSTMENTRATETYPE],
		--tgt.[FileName] = stg.[FileName],
		tgt.[FINANCIALREPORTINGEXCHANGERATETYPE] = stg.[FINANCIALREPORTINGEXCHANGERATETYPE],
		tgt.[FINANCIALREPORTINGTRANSLATIONTYPE] = stg.[FINANCIALREPORTINGTRANSLATIONTYPE],
		tgt.[INFLATIONADJUSTMENT_MX] = stg.[INFLATIONADJUSTMENT_MX],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		tgt.[LEDGERCHARTOFACCOUNTS] = stg.[LEDGERCHARTOFACCOUNTS],
		--tgt.[LSN] = stg.[LSN],
		tgt.[MAINACCOUNTID] = stg.[MAINACCOUNTID],
		tgt.[MAINACCOUNTTEMPLATE] = stg.[MAINACCOUNTTEMPLATE],
		tgt.[MANDATORYPAYMENTREFERENCE] = stg.[MANDATORYPAYMENTREFERENCE],
		tgt.[MODIFIEDBY] = stg.[MODIFIEDBY],
		tgt.[MODIFIEDDATETIME] = stg.[MODIFIEDDATETIME],
		tgt.[MONETARY] = stg.[MONETARY],
		tgt.[NAME] = stg.[NAME],
		tgt.[OFFSETLEDGERDIMENSION] = stg.[OFFSETLEDGERDIMENSION],
		tgt.[OPENINGACCOUNT] = stg.[OPENINGACCOUNT],
		tgt.[PARENTMAINACCOUNT] = stg.[PARENTMAINACCOUNT],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[POSTINGTYPE] = stg.[POSTINGTYPE],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		tgt.[REPOMOTYPE_MX] = stg.[REPOMOTYPE_MX],
		tgt.[REPORTINGACCOUNTTYPE] = stg.[REPORTINGACCOUNTTYPE],
		tgt.[REPORTINGEXCHANGEADJUSTMENTRATETYPE] = stg.[REPORTINGEXCHANGEADJUSTMENTRATETYPE],
		tgt.[SRUCODE] = stg.[SRUCODE],
		tgt.[STANDARDMAINACCOUNT_W] = stg.[STANDARDMAINACCOUNT_W],
		--tgt.[SysRowId] = stg.[SysRowId],
		tgt.[TRANSFERYEARENDACCOUNT_ES] = stg.[TRANSFERYEARENDACCOUNT_ES],
		tgt.[TYPE] = stg.[TYPE],
		tgt.[UNITOFMEASURE] = stg.[UNITOFMEASURE],
		tgt.[USERINFOID] = stg.[USERINFOID],
		tgt.[VALIDATECURRENCY] = stg.[VALIDATECURRENCY],
		tgt.[VALIDATEPOSTING] = stg.[VALIDATEPOSTING],
		tgt.[VALIDATEUSER] = stg.[VALIDATEUSER]
	 FROM [synapse_fo].[MAINACCOUNT] tgt
		INNER JOIN [staging_fo].[MAINACCOUNT] stg
			ON  stg.[RECID] = tgt.[RECID] 
		
END
